import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), q = nextInt();
        long[] a = new long[n]; // 0 = uncolored
        long pairs = 0;
        StringBuilder sb = new StringBuilder();
        for (int j = 0; j < q; j++) {
            int i = nextInt();
            long c = nextLong();
            // Only the two edges touching i can change: remove their old contribution, add the new one.
            if (a[i] != 0) {
                if (i > 0 && a[i - 1] == a[i]) pairs--;
                if (i + 1 < n && a[i + 1] == a[i]) pairs--;
            }
            a[i] = c;
            if (i > 0 && a[i - 1] == c) pairs++;
            if (i + 1 < n && a[i + 1] == c) pairs++;
            if (j > 0) sb.append(' ');
            sb.append(pairs);
        }
        System.out.println(sb);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, q := int(nextInt()), int(nextInt())
	a := make([]int64, n) // 0 = uncolored
	var pairs int64
	var out []byte
	for j := 0; j < q; j++ {
		i, c := int(nextInt()), nextInt()
		// Only the two edges touching i can change: remove their old contribution, add the new one.
		if a[i] != 0 {
			if i > 0 && a[i-1] == a[i] {
				pairs--
			}
			if i+1 < n && a[i+1] == a[i] {
				pairs--
			}
		}
		a[i] = c
		if i > 0 && a[i-1] == c {
			pairs++
		}
		if i+1 < n && a[i+1] == c {
			pairs++
		}
		if j > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, pairs, 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
